import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            N = int(next(iterator))
            markers = []
            for _ in range(N):
                markers.append(int(next(iterator)))

            adj = [[] for _ in range(N + 1)]
            for _ in range(N - 1):
                u = int(next(iterator))
                v = int(next(iterator))
                adj[u].append(v)
                adj[v].append(u)
        except StopIteration:
            break

        if N == 1:
            print(0)
            continue

        count = [0, 0, 0]
        for m in markers:
            count[m] += 1

        def can_achieve(k):
            if k == 0:
                if count[0] > 0 and count[1] > 0:
                    return False
                if count[1] > 0 and count[2] > 0:
                    return False
                return True

            if k >= 2:
                return True

            if k == 1:
                if count[0] > 0 and count[2] > 0:
                    if count[1] == 0:
                        return False
                return True

        if can_achieve(0):
            print(0)
        elif can_achieve(1):
            print(1)
        else:
            print(2)

if __name__ == "__main__":
    solve()
